diff --git a/apps/demo/src/styles.css b/apps/demo/src/styles.css
index 1bb4d64..3fc4ebc 100644
--- a/apps/demo/src/styles.css
+++ b/apps/demo/src/styles.css
@@ -180,3 +180,53 @@ h1 {
     font-size: 2.2rem;
   }
 }
+
+/* AgentHub scripted login form: start */
+.login-form {
+  display: grid;
+  gap: 20px;
+  margin-top: 22px;
+  min-width: 0;
+}
+
+.login-form label {
+  display: grid;
+  gap: 8px;
+  min-width: 0;
+  color: #31405c;
+  font-size: 0.875rem;
+  font-weight: 600;
+  line-height: 1.5;
+}
+
+.login-form input {
+  box-sizing: border-box;
+  width: 100%;
+  min-width: 0;
+  min-height: 48px;
+  padding: 12px 14px;
+  border: 1px solid #c9d5e6;
+  border-radius: 6px;
+  background: #ffffff;
+  color: #172033;
+  font: inherit;
+  font-size: 1rem;
+  font-weight: 400;
+  transition: border-color 120ms ease;
+}
+
+.login-form input::placeholder {
+  color: #65738b;
+  opacity: 1;
+}
+
+.login-form input:hover {
+  border-color: #93a8c4;
+}
+
+.login-form input:focus-visible {
+  border-color: #2563eb;
+  outline: 2px solid #2563eb;
+  outline-offset: 2px;
+}
+/* AgentHub scripted login form: end */
